import React, { useEffect, useState } from 'react';
import './Page1.css'; // Optional: For styling

const Page1 = () => {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    // Fetch data from the backend
    const fetchOrders = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/orders'); // Make sure this path matches your backend API
        const data = await response.json();
        setOrders(data);
      } catch (error) {
        console.error('Error fetching order data:', error);
      }
    };

    fetchOrders();
  }, []);

  // Function to update the status of the order
  const confirmOrder = async (orderId) => {
    try {
      const response = await fetch(`http://localhost:5000/api/orders/${orderId}/confirm`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      
      if (response.ok) {
        // Fetch updated orders after confirming the status
        const updatedOrders = orders.map(order => {
          if (order.orderId === orderId) {
            return {
              ...order,
              status: order.status.map(stage =>
                stage.stage === 'Order Confirmed' ? { ...stage, completed: true } : stage
              ),
            };
          }
          return order;
        });
        setOrders(updatedOrders);
        alert(`Order ${orderId} confirmed!`);
      }
    } catch (error) {
      console.error('Error updating order status:', error);
    }
  };
  
  return (
    <div className="table-container">
      <h2>Orders</h2>
      <table className="order-table">
        <thead>
          <tr>
            <th>Order ID</th>
            <th>Product Name</th>
            <th>Product Price</th>
            <th>Delivery Type</th>
          </tr>
        </thead>
        <tbody>
  {orders.length > 0 ? (
    orders.map((order) => (
      <tr key={order._id}>
        <td>{order.orderId}</td>
        <td>{order.productName}</td>
        <td>{order.productPrice}</td>
        <td>{order.deliveryType}</td>
      </tr>
    ))
  ) : (
    <tr>
      <td colSpan="4">No orders found</td>
    </tr>
  )}
</tbody>
      </table>
    </div>
  );
};

export default Page1;
